const ll MOD = 1e9 + 7;

ll pw(ll b, ll e, ll m = MOD) {
    ll r = 1; b %= m;
    while (e > 0) {
        if (e & 1) r = r * b % m;
        b = b * b % m;
        e >>= 1;
    }
    return r;
}

ll inv(ll a) { return pw(a, MOD - 2); }        // MOD must be prime

ll add(ll a, ll b) { return (a + b) % MOD; }
ll sub(ll a, ll b) { return (a - b % MOD + MOD) % MOD; }
ll mul(ll a, ll b) { return a % MOD * (b % MOD) % MOD; }

vector<int> cur;
vector<bool> used;

void backtrack(int depth) {
    if (depth == n) { process(cur); return; }
    for (int i = 0; i < n; i++) {
        if (used[i]) continue;
        used[i] = true;  cur.push_back(a[i]);      // choose
        backtrack(depth + 1);                       // explore
        cur.pop_back();  used[i] = false;           // UNDO
    }
}

